import {gestureGrid} from './gesture-motion.js?v=motion-v70';
function triangle(c,image,source,target){const [p0,p1,p2]=source,[q0,q1,q2]=target,det=(p1[0]-p0[0])*(p2[1]-p0[1])-(p2[0]-p0[0])*(p1[1]-p0[1]);if(Math.abs(det)<1e-8)return;const a=((q1[0]-q0[0])*(p2[1]-p0[1])-(q2[0]-q0[0])*(p1[1]-p0[1]))/det,b=((q1[1]-q0[1])*(p2[1]-p0[1])-(q2[1]-q0[1])*(p1[1]-p0[1]))/det,cc=((q2[0]-q0[0])*(p1[0]-p0[0])-(q1[0]-q0[0])*(p2[0]-p0[0]))/det,d=((q2[1]-q0[1])*(p1[0]-p0[0])-(q1[1]-q0[1])*(p2[0]-p0[0]))/det;
 c.save();c.beginPath();const center=[(q0[0]+q1[0]+q2[0])/3,(q0[1]+q1[1]+q2[1])/3];for(let i=0;i<3;i++){const q=target[i],length=Math.hypot(q[0]-center[0],q[1]-center[1])||1,p=[q[0]+(q[0]-center[0])/length*1.5,q[1]+(q[1]-center[1])/length*1.5];i?c.lineTo(...p):c.moveTo(...p)}c.closePath();c.clip();c.transform(a,b,cc,d,q0[0]-a*p0[0]-cc*p0[1],q0[1]-b*p0[0]-d*p0[1]);c.drawImage(image,0,0,960,540);c.restore()}
export function createGestureScene(){let buffer,output,lastImage,lastKey;
 return {paint(c,image,elapsed,f){const grid=gestureGrid(elapsed,f);buffer||=Object.assign(document.createElement('canvas'),{width:960,height:540});if(image!==lastImage||lastKey!==image.src){const b=buffer.getContext('2d');b.clearRect(0,0,960,540);const k=Math.max(960/image.naturalWidth,540/image.naturalHeight);b.drawImage(image,480-image.naturalWidth*k/2,270-image.naturalHeight*k/2,image.naturalWidth*k,image.naturalHeight*k);lastImage=image;lastKey=image.src}
 if(!grid.active){c.drawImage(buffer,0,0);return grid}output||=Object.assign(document.createElement('canvas'),{width:960,height:540});const mesh=output.getContext('2d');mesh.clearRect(0,0,960,540);mesh.drawImage(buffer,0,0);for(let y=0;y<grid.ny;y++)for(let x=0;x<grid.nx;x++){const i=y*(grid.nx+1)+x;for(const ids of [[i,i+1,i+grid.nx+2],[i,i+grid.nx+2,i+grid.nx+1]]){const ns=ids.map(j=>grid.nodes[j]);triangle(mesh,buffer,ns.map(n=>n.source),ns.map(n=>n.target))}}c.drawImage(output,0,0);return grid;
 }};
}
